          f(B, 'Avicenna', 'https://www.britannica.com/biography/Avicenna'),
          f(B, 'How long was The Canon of Medicine used as a medical textbook in Europe?', 'https://www.britannica.com/biography/How-long-was-The-Canon-of-Medicine-used-as-a-medical-textbook-in-Europe'),
